<script lang="ts">
 import Folder from '@lucide/svelte/icons/folder';
 export let name=''; export let kind='file'; export let size=16;
 const extension=()=>name.toLowerCase().split('.').pop()??'';
 const style=()=>{const ext=extension();if(kind==='directory')return {label:'',color:'#dcb67a'};if(['js','jsx','mjs','cjs'].includes(ext))return {label:'JS',color:'#e8d44d'};if(['ts','tsx'].includes(ext))return {label:'TS',color:'#4f9fe8'};if(['svelte','vue','html','htm'].includes(ext))return {label:ext==='svelte'?'S':'<>',color:'#ef6b4a'};if(['css','scss','sass','less'].includes(ext))return {label:'#',color:'#a979dc'};if(['json','yaml','yml','toml','xml'].includes(ext))return {label:'{}',color:'#e5ad4d'};if(['md','markdown','txt','log'].includes(ext))return {label:'TXT',color:'#8fa1b3'};if(['png','jpg','jpeg','gif','webp','svg','ico'].includes(ext))return {label:'IMG',color:'#bb80d9'};if(['sql','db','sqlite'].includes(ext))return {label:'DB',color:'#54a9d6'};if(['pdf'].includes(ext))return {label:'PDF',color:'#df5b5b'};return {label:(ext||'FILE').slice(0,4).toUpperCase(),color:'#8291a3'};};
</script>
{#if kind==='directory'}<Folder size={size} color="#dcb67a" aria-hidden="true"/>{:else}<span class="file-type" style={`--file-color:${style().color};width:${size}px;height:${Math.round(size*1.16)}px`} title={`${extension().toUpperCase()||'FILE'} file`}><i>{style().label}</i></span>{/if}
<style>.file-type{position:relative;display:grid;flex:none;place-items:end center;border:1px solid color-mix(in srgb,var(--file-color) 72%,#fff 10%);border-radius:2px;background:color-mix(in srgb,var(--file-color) 18%,#121216);color:var(--file-color);box-shadow:inset 0 0 0 1px #0003}.file-type::after{content:'';position:absolute;top:-1px;right:-1px;width:34%;height:28%;border-left:1px solid var(--file-color);border-bottom:1px solid var(--file-color);background:#111113;clip-path:polygon(0 0,100% 100%,0 100%)}.file-type i{width:100%;overflow:hidden;padding:0 1px 1px;font:700 6px/1 ui-monospace,monospace;text-align:center}</style>
